package net.officefloor.hq.app.setting;

/**
 * The settings of a sheet being saved, each null when it is left as it is: the clerk limit with two decimals,
 * "" for no limit, the floor with two decimals, the terms as a whole number of days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" for none, and the period numbering from-date as yyyy-MM-dd, "" for off, and the cap, the proof threshold and the note threshold, each with two decimals, "" for none, and the grace days as a whole number of days, "" for off, and the entry date as yyyy-MM-dd, "" for off.
 * {@code gradeTerms} are the terms of a grade's own being saved, as a whole number of days, by grade (a grade left out is left as it is).
 * {@code gradeGrace} are the grace days of a grade being saved, as a whole number of days, "" for none, by grade (a grade left out is left as it is).
 * {@code gradeProof} are the proof thresholds of a grade being saved, with two decimals, "" for none (the sheet's is in force), by grade (a grade left out is left as it is).
 * {@code gradeClerkLimit} are the clerk limits of a grade being saved, with two decimals, "" for none (the sheet's is in force), by grade (a grade left out is left as it is).
 * {@code perms} are the roles each action is permitted to being saved, by action in {@link Settings#PERM_ACTIONS} order, as a comma separated list, "" for the standing rule.
 * {@code pot} is the pot being saved, with two decimals, "" for none (not dated).
 * {@code parent} is the id of the parent sheet being saved, "" for none (not dated).
 * {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on being saved (not dated).
 * {@code alertThreshold} is the alert threshold being saved, with two decimals, "" for off (not dated).
 * {@code rounding} is the rounding mode being saved, half-up or half-even, "" for none (dated).
 * {@code reviewThreshold} is the review threshold being saved, with two decimals, "" for none (dated).
 * {@code escalateAfter} is the escalation gap being saved, as a whole number of days, "" for off (not dated).
 * {@code reviewSla} is the review SLA being saved, as a whole number of days, "" for none (not dated).
 * {@code proofKinds} are the proof kinds being saved, receipt or photo, comma separated without repeats, "" for none (not dated).
 * {@code defaultGrade} is the default grade being saved, A, B or C, "" for none (so A; not dated).
 * {@code from} is the from-date given for a dated setting, by setting key (a key left out is saved from the sheet's today, and audited without one).
 */
public record SheetSettings(String sheetId, String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.SortedMap<String, String> gradeTerms, java.util.SortedMap<String, String> gradeGrace, java.util.Map<String, java.time.LocalDate> from,
        java.util.Map<String, String> perms, java.util.SortedMap<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        java.util.SortedMap<String, String> gradeClerkLimit) {
}
package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap, the proof threshold and the note threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the entry date (null: left as it is; blank: off, so the sheet's today), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the grace days of a grade, by grade (each left out or null: left as it is; blank: none), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule), and the proof threshold of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's), and the pot (null: left as it is; blank: none), and the parent sheet's id (null: left as it is; blank: none), and the fiscal year start month (null or blank: left as it is), and the alert threshold (null: left as it is; blank: off), and the rounding mode (null: left as it is; blank: none, so the policy date decides), and the review threshold (null: left as it is; blank: none), and the escalation gap in days (null: left as it is; blank: off), and the review SLA in days (null: left as it is; blank: none), and the proof kinds, comma separated (null: left as it is; blank: none), and the default grade (null: left as it is; blank: none, so A), and the clerk limit of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> gradeGrace, java.util.Map<String, String> from, java.util.Map<String, String> perms,
        java.util.Map<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        java.util.Map<String, String> gradeClerkLimit) {
}
package net.officefloor.hq.app.setting;

/** The sheet's settings as the screen sees them, each dated one as it is in force on the sheet's today: the clerk limit with two decimals, "" when there is none, the floor with two decimals, the terms in days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" when there is none (the sheet's today is), and the period numbering from-date as yyyy-MM-dd, "" when it is off, and the terms in force for each grade, in days (its own, or the sheet's terms when it has none), and the cap with two decimals, "" when there is none. {@code dated} is every value recorded for each dated setting, by setting key, by from-date. {@code perms} is the roles each action is permitted to, by action, as a comma separated list, "" for the standing rule. {@code graceDays} is the grace days, "" when they are off. {@code entryDate} is the entry date as yyyy-MM-dd, "" when it is off. {@code pot} is the pot with two decimals, "" when there is none. {@code parent} is the parent sheet's id, "" when there is none. {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on. {@code alertThreshold} is the alert threshold with two decimals, "" when alerts are off. {@code escalateAfter} is the escalation gap in days, "" when it is off. {@code reviewSla} is the review SLA in days, "" when there is none. {@code proofKinds} are the proof kinds, comma separated, "" when there are none. {@code defaultGrade} is the default grade, "" when there is none (A is). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, java.util.List<Settings.DatedValue>> dated,
        java.util.Map<String, String> perms, String graceDays, String entryDate, String pot, String parent, String fiscalStartMonth, String alertThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, Settings settings, Sheets sheets,
            ObjectResponse<SettingsResponse> response) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.today(sheet);
        response.send(new SettingsResponse(settings.current(sheet, Settings.CLERK_LIMIT),
                settings.floor(sheet, today).setScale(2).toPlainString(), Integer.toString(settings.terms(sheet, today)),
                settings.latePct(sheet, today).setScale(2).toPlainString(), settings.get(sheet, Settings.POLICY_DATE),
                settings.get(sheet, Settings.PERIOD_NUMBERING_FROM), gradeTerms(settings, sheet, today),
                settings.current(sheet, Settings.CAP), dated(settings, sheet), perms(settings, sheet),
                settings.get(sheet, Settings.GRACE_DAYS), settings.get(sheet, Settings.ENTRY_DATE),
                settings.get(sheet, Settings.POT), settings.parent(sheet),
                Integer.toString(settings.fiscalStartMonth(sheet)), settings.get(sheet, Settings.ALERT_THRESHOLD),
                settings.get(sheet, Settings.ESCALATE_AFTER), settings.get(sheet, Settings.REVIEW_SLA),
                settings.get(sheet, Settings.PROOF_KINDS), settings.get(sheet, Settings.DEFAULT_GRADE)));
    }

    private static Map<String, String> gradeTerms(Settings settings, String sheet, LocalDate today) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) {
            terms.put(grade, Integer.toString(settings.terms(sheet, grade, today)));
        }
        return terms;
    }

    private static Map<String, String> perms(Settings settings, String sheet) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : Settings.PERM_ACTIONS) {
            perms.put(action, settings.perm(sheet, action));
        }
        return perms;
    }

    private static Map<String, List<Settings.DatedValue>> dated(Settings settings, String sheet) {
        Map<String, List<Settings.DatedValue>> dated = new LinkedHashMap<>();
        for (String key : Settings.DATED) {
            dated.put(key, settings.history(sheet, key));
        }
        return dated;
    }
}
    /** Days after a period's to-date it stays open once the sheet's today passes it (undated); blank is off. */
    public static final String GRACE_DAYS = "grace-days";
    /** The amount a balanced pool's members cut by their shares (undated), with two decimals; blank is none. */
    public static final String POT = "pot";
    /** The id of the sheet whose rates are used where this sheet has none (undated); blank is none. */
    public static final String PARENT = "parent";
    /** The month (1 to 12) a fiscal year starts on (undated); blank is the default, January. */
    public static final String FISCAL_START_MONTH = "fiscal-start-month";
    public static final String FISCAL_START_MONTH_DEFAULT = "1";
    /** The due-total above which a person is alerted (undated), with two decimals; blank is off. */
    public static final String ALERT_THRESHOLD = "alert-threshold";
    /** The escalation gap, in days (not dated; blank: off). */
    public static final String ESCALATE_AFTER = "escalate-after";
    /** The review SLA, in days (not dated; blank: none): a REVIEW claim is late once its review day plus these is before the sheet's today. */
    public static final String REVIEW_SLA = "review-sla";
    /** The proof kinds a claim above the proof threshold needs one proof of each of (not dated; blank: none), comma separated. */
    public static final String PROOF_KINDS = "proof-kinds";
    /** The grade a person quick-added or imported with a blank grade is given (not dated); "" is grade A. */
    public static final String DEFAULT_GRADE = "default-grade";
    /** How a claim's live figures round (dated): half-up or half-even; blank is none, so the policy date decides. */
    public static final String ROUNDING = "rounding";
    /** The sheet's default grade: the one set, else A. */
    public String defaultGrade(String sheetId) {
        String value = get(sheetId, DEFAULT_GRADE);
        return value.isEmpty() ? "A" : value;
    }

    public List<String> proofKinds(String sheetId) {
        String value = get(sheetId, PROOF_KINDS);
        return value.isEmpty() ? List.of() : List.of(value.split(","));
    }

    /** The review SLA, in days; null when there is none. */
    public Integer reviewSla(String sheetId) {
        String value = get(sheetId, REVIEW_SLA);
        return value.isEmpty() ? null : Integer.valueOf(value);
    }

    /** The alert threshold, with two decimals; null when alerts are off. */
    public BigDecimal alertThreshold(String sheetId) {
        String value = get(sheetId, ALERT_THRESHOLD);
        return value.isEmpty() ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when it is
     * dated before the policy date, half to even on or after it. A correction rounds by the date of the claim it corrects.
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Map;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
    private static final Pattern MONTH = Pattern.compile("\\d{1,2}");
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");

    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
    // and only a grade (A, B or C) may have them.
    // A grade's grace days are dated like its terms: blank is none, otherwise a whole number of days, 0 or more, and only for a grade (A, B or C).
            grace = Integer.toString(Integer.parseInt(grace));
        }
        String escalateAfter = body == null || body.escalateAfter() == null ? null : body.escalateAfter().trim();
        if (escalateAfter != null && !escalateAfter.isEmpty()) {
            if (!DAYS.matcher(escalateAfter).matches()) {
                throw new InvalidSettingException("The escalation gap must be a whole number of days, 0 or more.");
            }
            escalateAfter = Integer.toString(Integer.parseInt(escalateAfter));
        }
        String reviewSla = body == null || body.reviewSla() == null ? null : body.reviewSla().trim();
        if (reviewSla != null && !reviewSla.isEmpty()) {
            if (!DAYS.matcher(reviewSla).matches()) {
                throw new InvalidSettingException("The review SLA must be a whole number of days, 0 or more.");
            }
            reviewSla = Integer.toString(Integer.parseInt(reviewSla));
        }
        String entryDate = body == null || body.entryDate() == null ? null : body.entryDate().trim();
        if (entryDate != null && !entryDate.isEmpty()) {
            try {
                entryDate = LocalDate.parse(entryDate).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The entry date must be a date (yyyy-mm-dd).");
            }
        }
        String pot = body == null || body.pot() == null ? null : body.pot().trim();
        if (pot != null && !pot.isEmpty()) {
            if (!AMOUNT.matcher(pot).matches()) {
                throw new InvalidSettingException("The pot must be an amount of 0.00 or more, with up to two decimals.");
            }
            pot = twoDecimals(pot);
        }
        String alertThreshold = body == null || body.alertThreshold() == null ? null : body.alertThreshold().trim();
        if (alertThreshold != null && !alertThreshold.isEmpty()) {
            if (!AMOUNT.matcher(alertThreshold).matches()) {
                throw new InvalidSettingException("The alert threshold must be an amount of 0.00 or more, with up to two decimals.");
            }
            alertThreshold = twoDecimals(alertThreshold);
        }
        String parent = body == null || body.parent() == null ? null : body.parent().trim();
        if (parent != null && !parent.isEmpty()) {
            String sheet = sheetId.trim();
            if (parent.equals(sheet)) {
                throw new InvalidSettingException("A sheet cannot be its own parent.");
            }
            if (!sheets.exists(parent)) {
                throw new InvalidSettingException("The parent must be a sheet that exists.");
            }
            java.util.Set<String> seen = new java.util.HashSet<>();
            for (String at = parent; !at.isEmpty() && seen.add(at); at = store.parent(at)) {
                if (at.equals(sheet)) {
                    throw new InvalidSettingException("The parent cannot be a sheet that has this sheet as an ancestor.");
                }
            }
        }
        String fiscalStartMonth = body == null || body.fiscalStartMonth() == null || body.fiscalStartMonth().isBlank() ? null
                : body.fiscalStartMonth().trim();
        if (fiscalStartMonth != null) {
            if (!MONTH.matcher(fiscalStartMonth).matches() || Integer.parseInt(fiscalStartMonth) < 1 || Integer.parseInt(fiscalStartMonth) > 12) {
                throw new InvalidSettingException("The fiscal year start month must be a month, 1 to 12.");
            }
            fiscalStartMonth = Integer.toString(Integer.parseInt(fiscalStartMonth));
        }
        String rounding = body == null || body.rounding() == null ? null : body.rounding().trim();
        if (rounding != null && !rounding.isEmpty() && !Settings.ROUNDING_MODES.contains(rounding)) {
            throw new InvalidSettingException("The rounding mode must be half-up or half-even.");
        }
        String proofKinds = body == null || body.proofKinds() == null ? null : body.proofKinds().trim();
        if (proofKinds != null && !proofKinds.isEmpty()) {
            java.util.List<String> kinds = new java.util.ArrayList<>();
            for (String kind : proofKinds.split(",")) {
                String k = kind.trim();
                if (!net.officefloor.hq.app.claim.ProofRequest.KINDS.contains(k)) {
                    throw new InvalidSettingException("The proof kinds must be receipt or photo, separated by commas.");
                }
                if (!kinds.contains(k)) {
                    kinds.add(k);
                }
            }
            proofKinds = String.join(",", kinds);
        }
        String defaultGrade = body == null || body.defaultGrade() == null ? null : body.defaultGrade().trim();
        if (defaultGrade != null && !defaultGrade.isEmpty() && !Settings.GRADES.contains(defaultGrade)) {
            throw new InvalidSettingException("The default grade must be A, B or C.");
        }
        Map<String, LocalDate> from = new java.util.HashMap<>();
        if (body != null && body.from() != null) {
            for (Map.Entry<String, String> entry : body.from().entrySet()) {
                String key = entry.getKey() == null ? "" : entry.getKey().trim();
                String date = entry.getValue() == null ? "" : entry.getValue().trim();
                if (date.isEmpty()) {
                    continue;
                }
                if (!Settings.DATED.contains(key)) {
                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
                }
                try {
                    from.put(key, LocalDate.parse(date));
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
                }
            }
        }
        Map<String, String> perms = new java.util.LinkedHashMap<>();
        if (body != null && body.perms() != null) {
            for (String action : body.perms().keySet()) {
                if (!Settings.PERM_ACTIONS.contains(action)) {
                    throw new InvalidSettingException("Permissions are set only for open, settle, void, reassign, close and reopen.");
                }
            }
            for (String action : Settings.PERM_ACTIONS) {
                String typedRoles = body.perms().get(action);
                if (typedRoles == null) {
                    continue;
                }
                java.util.List<String> roles = new java.util.ArrayList<>();
                if (!typedRoles.isBlank()) {
                    for (String role : typedRoles.split(",")) {
                        String r = role.trim();
                        if (!Settings.ROLES.contains(r)) {
                            throw new InvalidSettingException("The roles allowed to " + action + " must be clerk or steward, separated by commas.");
                        }
                        if (!roles.contains(r)) {
                            roles.add(r);
                        }
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
